<script setup lang="ts">
import { ref, reactive, onMounted, inject, computed } from 'vue'
import { X, ArrowUpRight } from 'lucide-vue-next'
import { api, session, label, date, localTime, describeError, type Data } from '../api'
const props=defineProps<{options:{id?:string,create?:boolean,edit?:boolean}}>(), emit=defineEmits(['close','saved'])
const notify=inject<(s:string,e?:boolean)=>void>('notify')!, requireLogin=inject<()=>void>('requireLogin')!, openGroup=inject<(a:Data)=>void>('openGroup')!
const activity=ref<Data|null>(null), busy=ref(false), loading=ref(true), error=ref(''), note=ref(''), reporting=ref(false), report=reactive({reason:'',evidence:''})
const future=new Date(Date.now()+86400000), form=reactive<Data>({title:'',type:'STUDY',description:'',campus:'主校区',tags:'',capacity:4,startAt:localTime(future),endAt:localTime(new Date(+future+3600000)),deadline:localTime(new Date(+future-3600000)),confirmationDeadline:localTime(future),publicLocation:'',exactLocation:'',publicLat:'',publicLon:''})
const editing=computed(()=>props.options.create||props.options.edit)
const owner=computed(()=>activity.value?.ownerId===session.user?.id)
const canApply=computed(()=>activity.value&&activity.value.status==='OPEN'&&activity.value.remaining>0&&Date.now()<new Date(activity.value.deadline).getTime()&&!owner.value&&!activity.value.groupId)
onMounted(async()=>{try{if(props.options.id){activity.value=await api('/activities/'+props.options.id);if(props.options.edit){Object.assign(form,activity.value);form.tags=(activity.value!.tags||[]).join('，');for(const k of ['startAt','endAt','deadline','confirmationDeadline'])form[k]=localTime(activity.value![k]);form.publicLat=activity.value!.publicLat??'';form.publicLon=activity.value!.publicLon??''}}}catch(e){error.value=describeError(e)}finally{loading.value=false}})
async function save(){busy.value=true;error.value='';try{const body:Data={...form,tags:String(form.tags).split(/[,，]/).map(s=>s.trim()).filter(Boolean)};for(const k of ['startAt','endAt','deadline','confirmationDeadline'])body[k]=new Date(form[k]).toISOString();for(const k of ['publicLat','publicLon'])body[k]=form[k]===''?null:Number(form[k]);if(props.options.edit)body.expectedVersion=activity.value!.version;
 await api('/activities'+(props.options.edit?'/'+props.options.id:''),props.options.edit?'PATCH':'POST',body,!props.options.edit);notify(props.options.edit?'活动已更新，相关成员将收到通知':'发布成功，开始寻找同行者吧');emit('saved');emit('close')}catch(e){error.value=describeError(e)}finally{busy.value=false}}
async function apply(){if(!session.user){requireLogin();return}busy.value=true;error.value='';try{await api(`/activities/${activity.value!.id}/applications`,'POST',{note:note.value},true);notify('申请已提交，等待发起人审核');emit('saved');emit('close')}catch(e){error.value=describeError(e)}finally{busy.value=false}}
async function submitReport(){if(!session.user){requireLogin();return}busy.value=true;error.value='';try{await api('/reports','POST',{targetType:'ACTIVITY',targetId:activity.value!.id,...report});notify('举报已提交，可在举报与申诉中查看进度');reporting.value=false;report.reason='';report.evidence=''}catch(e){error.value=describeError(e)}finally{busy.value=false}}
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="activity-title"><button class="modal-close icon-button" aria-label="关闭活动窗口" @click="emit('close')"><X/></button><span class="eyebrow">A PLAN WORTH SHARING</span><h2 id="activity-title">{{editing?(options.edit?'编辑行动计划':'发起一个行动'):activity?.title||'活动详情'}}</h2><p v-if="loading" class="loading">正在加载活动…</p>
 <form v-if="editing&&!loading" @submit.prevent="save"><div class="form-grid"><label class="full">行动标题<input v-model="form.title" required maxlength="80" placeholder="例如：周三晚一起在图书馆自习"/></label><label>活动类型<select v-model="form.type"><option v-for="t in ['STUDY','SPORT','MEAL','TRAVEL','OTHER']" :key="t" :value="t">{{label(t)}}</option></select></label><label>人数上限（包含自己）<input v-model.number="form.capacity" type="number" min="1" max="2147483647" required/></label><label>开始时间<input v-model="form.startAt" type="datetime-local" required/></label><label>结束时间<input v-model="form.endAt" type="datetime-local" required/></label><label>报名截止<input v-model="form.deadline" type="datetime-local" required/></label><label>参加确认截止<input v-model="form.confirmationDeadline" type="datetime-local" required/></label><p class="field-help full">报名截止 ≤ 参加确认截止 ≤ 开始时间 &lt; 结束时间。请假保留名额，退出才释放名额。</p><label>校区<input v-model="form.campus" maxlength="40" required/></label><label>公开集合地点<input v-model="form.publicLocation" maxlength="120" required placeholder="例如：图书馆"/></label><label class="full">精确集合点（可选）<input v-model="form.exactLocation" maxlength="300" placeholder="默认隐藏，可在我的资料中同意向组员分享"/></label><label class="full">标签（逗号分隔，最多10个）<input v-model="form.tags" placeholder="自习，期中复习"/></label><label>公开地点纬度（可选）<input v-model="form.publicLat" type="number" min="-90" max="90" step="any"/></label><label>公开地点经度（可选）<input v-model="form.publicLon" type="number" min="-180" max="180" step="any"/></label><label class="full">行动说明<textarea v-model="form.description" maxlength="2000" placeholder="写下目标、准备事项和你期待的同行方式。"></textarea></label></div><div v-if="error" class="error-box" role="alert">{{error}}</div><div class="modal-actions"><button type="button" class="secondary" @click="emit('close')">暂不发布</button><button type="submit" class="primary" :disabled="busy">{{busy?'正在保存…':options.edit?'保存变更并通知':'发布行动'}}</button></div></form>
 <template v-else-if="activity&&!loading"><div class="actions"><span :class="['category',activity.type]">{{label(activity.type)}}</span><span class="badge">{{label(activity.status)}}</span><span class="subtle">已加入 {{activity.occupied}} / {{activity.capacity}} 人</span></div><dl class="detail-meta"><div><dt>开始</dt><dd>{{date(activity.startAt)}}</dd></div><div><dt>结束</dt><dd>{{date(activity.endAt)}}</dd></div><div><dt>报名截止</dt><dd>{{date(activity.deadline)}}</dd></div><div><dt>参加确认截止</dt><dd>{{date(activity.confirmationDeadline)}}</dd></div><div><dt>集合地点</dt><dd>{{activity.publicLocation}} · {{activity.campus}}</dd></div><div><dt>精确集合点</dt><dd>{{activity.exactLocation||'发起人尚未向你分享'}}</dd></div></dl><p class="detail-description">{{activity.description||'发起人还没有添加更多说明。'}}</p><div class="tags"><span v-for="t in activity.tags" :key="t"># {{t}}</span></div><form v-if="canApply" @submit.prevent="apply"><label>给发起人的留言（可选）<textarea v-model="note" maxlength="300" placeholder="简单说说你的计划，让彼此更了解。"></textarea></label><p class="field-help">提交申请不会占用名额，审核通过后才正式加入。</p><button class="primary" :disabled="busy" type="submit">{{busy?'正在提交…':'申请一起行动'}}<ArrowUpRight :size="16"/></button></form><div v-else-if="activity.groupId" class="actions"><button class="primary" @click="openGroup(activity!);emit('close')">进入临时小组</button><span class="subtle">成员状态可在「我的行动」中维护</span></div><p v-else class="warning-box">{{owner?'这是你发起的活动，请在「我的行动」中审核申请。':activity.remaining<=0?'当前名额已满。':'当前活动已关闭申请。'}}</p><div v-if="error" class="error-box" role="alert">{{error}}</div><div class="modal-actions"><button class="text-button" @click="reporting=!reporting">举报此活动</button><button class="secondary" @click="emit('close')">关闭详情</button></div><form v-if="reporting" class="report-form stack" @submit.prevent="submitReport"><label>举报理由<textarea v-model="report.reason" required maxlength="1000"></textarea></label><label>可核实的证据说明<textarea v-model="report.evidence" maxlength="2000"></textarea></label><button class="danger" :disabled="busy">提交举报</button></form></template><div v-else-if="error" class="error-box" role="alert">{{error}}</div>
</section></div></template>
